from itertools import product
import heapq
from collections import Counter


def _dependency_resolver(data, name_order, preference):
    packages = data["packages"]
    names = sorted(packages, reverse=(name_order == "descending"))
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})

    domains = []
    for name in names:
        versions = [row["version"] for row in packages[name]
                    if row["version"] not in blocked.get(name, [])
                    and (name not in pins or row["version"] == pins[name])]
        versions = sorted(set(versions), reverse=(preference == "maximum"))
        domains.append([-1] + versions if preference == "minimum" else versions + [-1])

    roots = data["roots"]
    for values in product(*domains):
        selected = {name: version for name, version in zip(names, values)
                    if version != -1}
        valid = True
        for name, bounds in roots.items():
            version = selected.get(name)
            if version is None or not bounds[0] <= version <= bounds[1]:
                valid = False
                break
        if not valid:
            continue

        edges = {}
        closure = set(roots)
        for name, version in selected.items():
            row = next(row for row in packages[name] if row["version"] == version)
            active = []
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                active.append(dep)
                target = selected.get(dep["name"])
                if target is None or not dep["min"] <= target <= dep["max"]:
                    valid = False
                    break
                closure.add(dep["name"])
            edges[name] = [dep["name"] for dep in active]
            if not valid:
                break
        if not valid or closure != set(selected):
            continue

        finished, active_path = set(), set()

        def visit(node):
            if node in active_path:
                return False
            if node in finished:
                return True
            active_path.add(node)
            if any(not visit(child) for child in edges.get(node, [])):
                return False
            active_path.remove(node)
            finished.add(node)
            return True

        if not all(visit(node) for node in edges):
            continue
        return {"versions": selected}
    return {"error": "unsatisfiable"}


def _build_component_01():
    return lambda data: _dependency_resolver(data, "ascending", "maximum")


def _build_component_02():
    return lambda data: _dependency_resolver(data, "ascending", "minimum")


def _build_component_03():
    return lambda data: _dependency_resolver(data, "descending", "maximum")


def _build_component_04():
    return lambda data: _dependency_resolver(data, "descending", "minimum")


def _build_component_05():
    return lambda data: _dependency_resolver(data, "ascending", "maximum")


def _build_component_06():
    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        winners = {}
        for position, event in enumerate(data["events"]):
            if event.get("sequence", 0) > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            key = (event.get("revision", 0), position)
            if event_id not in winners or key > winners[event_id][0]:
                winners[event_id] = (key, event)

        balances = dict(data.get("opening", {}))

        def rounded(num, den):
            if data["rounding"] == "half_up":
                return (num + den // 2) // den
            return num // den

        for _, event in winners.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), 10000)
            tax = rounded(net * event.get("tax_bp", 0), 10000)
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _build_component_07():
    def solve(data):
        jobs = [job for job in data["jobs"]
                if job["id"] not in data.get("blocked", [])]
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        k = data["k"]
        best_ids = None
        best_value = None

        for subset in _subsets(jobs, k):
            ids = [job["id"] for job in subset]
            id_set = set(ids)
            if not mandatory.issubset(id_set):
                continue
            counts = Counter(job["group"] for job in subset)
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            if any(counts.get(group, 0) > k
                   for group in set(counts) - set(quotas)):
                continue
            events = []
            for job in subset:
                events.append((job["start"], 1))
                events.append((job["end"], -1))
            overlap = 0
            feasible = True
            for _, delta in sorted(events):  # ends (-1) precede starts (+1)
                overlap += delta
                if overlap > 2:
                    feasible = False
                    break
            if not feasible:
                continue
            sorted_ids = sorted(ids)
            value = sum(job["value"] for job in subset)
            if (best_value is None or value > best_value or
                    (value == best_value and sorted_ids < best_ids)):
                best_value, best_ids = value, sorted_ids
        if best_ids is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}
    return solve


def _subsets(items, size):
    # Iterative combinations avoids imposing a dependency on the job ordering.
    from itertools import combinations
    return combinations(items, size)


def _build_component_08():
    def solve(data):
        required = data.get("required", [])
        bit_for = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        source = data["source"]
        initial_mask = bit_for.get(source, 0)
        start = data["start"]
        # Distances are keyed by all state components, including coupon budget.
        initial = (source, initial_mask, data["coupons"])
        distance = {initial: start}
        queue = [(start, source, initial_mask, data["coupons"])]
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        while queue:
            time, node, mask, coupons = heapq.heappop(queue)
            state = (node, mask, coupons)
            if distance.get(state) != time:
                continue
            if node == data["target"] and mask == full:
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], coupons)]
                if coupons:
                    duration = max(2, edge["duration"] - edge.get("discount", 0))
                    options.append((duration, coupons - 1))
                for duration, remaining in options:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    next_node = edge["v"]
                    next_mask = mask | bit_for.get(next_node, 0)
                    next_state = (next_node, next_mask, remaining)
                    if arrival < distance.get(next_state, float("inf")):
                        distance[next_state] = arrival
                        heapq.heappush(queue, (arrival, next_node, next_mask, remaining))
        return {"arrival": None}
    return solve


SOLVERS = {
    "component_01": _build_component_01(),
    "component_02": _build_component_02(),
    "component_03": _build_component_03(),
    "component_04": _build_component_04(),
    "component_05": _build_component_05(),
    "component_06": _build_component_06(),
    "component_07": _build_component_07(),
    "component_08": _build_component_08(),
}
